  const path=resolve(text(configPath,4096,'incident sources configuration path'));
  let config,bytes;
  try {bytes=await readPrivateFile(path,MAX_CONFIG_BYTES);config=JSON.parse(decoder.decode(bytes));}
  catch(error) {
