        json(res, 200, {report});
      } catch (error) {
        const status = Number(error?.status) || (error instanceof TypeError ? 422 : 502);
        json(res, status, {error: status === 502 ? 'ORIGINAL_INTAKE_FAILED' : 'INVALID_INTAKE',
